from sage.all import *
from Crypto.Util.number import bytes_to_long, long_to_bytes

n = Integer()
e = 16
ct = Integer()
P = PolynomialRing(Zmod(n), names = 'x')

x= P.gen()
prefix_bytes = b"crypto{"
suffix_bytes = b"}"

# Tính shift theo số byte
len_x = 16
len_suffix = len(suffix_bytes)

val_prefix = bytes_to_long(prefix_bytes)
val_suffix = bytes_to_long(suffix_bytes)

# Đa thức biểu diễn m(x)
m = val_prefix * (256 ** (len_x + len_suffix)) + x * (256**len_suffix) + val_suffix
f = m**e - ct
f = f.monic
X = 256^len_x
roots = f.small_roots(X = X, beta = 1.0)
if roots:
    x_val = Integer(roots[0])
    recovered_msg = (
        val_prefix * (256 ** (len_x + len_suffix))
        + x_val * (256**len_suffix)
        + val_suffix
    )
    print("[+] FLAG:", long_to_bytes(int(recovered_msg)).decode())
else:
    print("[-] Không tìm thấy nghiệm. Kiểm tra lại độ dài byte của phần bí mật!")